begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
select ok(to_regclass('private.waitlist_enrollments') is not null,'private waitlist enrollment exists');
select private.configure_policy_environment('development');
grant select on public.orders,public.order_items,public.tickets to service_role;
\ir ../../supabase/tests/database/helpers/spec09_refund_setup.inc
reset role;
revoke select on public.orders,public.order_items,public.tickets from service_role;
select ok((select not accepting_joins and not observer_enabled and not delivery_enabled from private.waitlist_settings),'gates default off');
select is(public.server_join_waitlist('a6200000-0000-4000-8000-000000000001','a6300000-0000-4000-8000-000000000001','Buyer','disabled@example.invalid',gen_random_uuid(),repeat('a',64))->>'kind','WAITLIST_UNAVAILABLE','default join closed');
update private.waitlist_settings set accepting_joins=true,observer_enabled=true,delivery_enabled=true,sender_email='notify@example.invalid',reply_to='support@example.invalid',app_origin='https://example.invalid',worker_healthy_at=clock_timestamp(),capacity_minute=10000,capacity_day=10000,capacity_month=10000;
create temp table wlproof(k text primary key,v jsonb);
insert into wlproof values('orders',(select jsonb_agg(to_jsonb(o) order by id) from public.orders o));
select is(public.server_join_waitlist('a6200000-0000-4000-8000-000000000001','a6300000-0000-4000-8000-000000000001','Buyer','buyer@example.invalid',gen_random_uuid(),repeat('a',64))->>'kind','TICKETS_AVAILABLE','available denied');
update public.ticket_tiers set quantity_total=2 where id='a6300000-0000-4000-8000-000000000001';
insert into wlproof values('request',to_jsonb(gen_random_uuid()));
select is(public.server_join_waitlist('a6200000-0000-4000-8000-000000000001','a6300000-0000-4000-8000-000000000001','Buyer',' Buyer@Example.Invalid ',(select (v#>>'{}')::uuid from wlproof where k='request'),repeat('b',64))->>'kind','joined','sold-out join');
select is(public.server_join_waitlist('a6200000-0000-4000-8000-000000000001','a6300000-0000-4000-8000-000000000001','Another','buyer@example.invalid',gen_random_uuid(),repeat('b',64))->>'kind','joined','duplicate generic success');
select is((select count(*) from private.waitlist_enrollments),1::bigint,'one enrollment');
select is((select name from private.waitlist_enrollments),'Buyer','duplicate cannot rename');
select is((select count(*) from private.waitlist_deliveries),1::bigint,'one confirmation');
select is((select jsonb_agg(to_jsonb(o) order by id) from public.orders o),(select v from wlproof where k='orders'),'join reserves nothing');
update public.ticket_tiers set quantity_total=3 where id='a6300000-0000-4000-8000-000000000001';
select public.server_observe_waitlist('a6300000-0000-4000-8000-000000000001');
select is((select count(*) from private.waitlist_availability_cycles),1::bigint,'observed restock cycle');
select is((select count(*) from private.waitlist_deliveries where purpose='restock'),1::bigint,'one restock');
select public.server_observe_waitlist('a6300000-0000-4000-8000-000000000001');
select is((select count(*) from private.waitlist_availability_cycles),1::bigint,'continuous availability no cycle');
select ok(not has_table_privilege('authenticated','private.waitlist_enrollments','select'),'browser table private');
select ok(not has_function_privilege('anon','public.server_join_waitlist(uuid,uuid,text,text,uuid,text)','execute'),'join RPC service only');
select set_config('request.jwt.claim.sub','a6100000-0000-4000-8000-000000000002',true);
select throws_ok($$select public.get_owned_waitlist('a6200000-0000-4000-8000-000000000001')$$,'P0001','WAITLIST_UNAVAILABLE','foreign owner denied');
select set_config('request.jwt.claim.sub','a6100000-0000-4000-8000-000000000001',true);
select is(public.get_owned_waitlist('a6200000-0000-4000-8000-000000000001')->'tiers'->0->>'waiting','1','owner waiting count');
select public.remove_owned_waitlist('a6200000-0000-4000-8000-000000000001','a6300000-0000-4000-8000-000000000001',(select id from private.waitlist_enrollments));
delete from private.waitlist_rate_events; -- Isolate request replay from the separately tested attempt budget.
select is(public.server_join_waitlist('a6200000-0000-4000-8000-000000000001','a6300000-0000-4000-8000-000000000001','Buyer',' Buyer@Example.Invalid ',(select (v#>>'{}')::uuid from wlproof where k='request'),repeat('c',64))->>'kind','joined','lost response does not rejoin removed');
select is((select count(*) from private.waitlist_enrollments where lifecycle='active'),0::bigint,'removed stays removed');
select ok(to_regprocedure('public.server_prune_waitlist()') is not null,'safe retention RPC exists');
select ok(to_regprocedure('public.server_configure_waitlist(jsonb)') is not null,'service-only configuration exists');
select is(private.organizer_message_audience('a6200000-0000-4000-8000-000000000001','{"kind":"everyone"}'),'[]'::jsonb,'waitlist-only demand is never Email Attendees audience');
select public.duplicate_owned_event('a6200000-0000-4000-8000-000000000001','a6200000-0000-4000-8000-000000000090',private.event_duplicate_fingerprint(private.event_duplicate_configuration('a6200000-0000-4000-8000-000000000001')));
select is((select count(*) from private.waitlist_enrollments where event_id='a6200000-0000-4000-8000-000000000090'),0::bigint,'Duplicate Event creates no waitlist enrollment');
select is((select count(*) from private.waitlist_tier_state where event_id='a6200000-0000-4000-8000-000000000090'),0::bigint,'Duplicate Event creates no waitlist cycle state');
select ok(not private.storefront_handle_valid('waitlist'),'leave route reserved against organizer handle collision');
select * from finish();
rollback;
